mapper.select:
select t.theme_id as id, t.theme_name as `name`, count(*) as total_num from safety_cultivate_task t left join market_config mc on mc.market_tenant = t.market_tenant
mc.status = true
and t.market_tenant = #{query.marketTenant}
and t.cultivate_start_time >= #{query.period.begin} and t.cultivate_start_time < #{query.period.end}
group by t.theme_id,t.theme_name

select
count(DISTINCT t.id) as total_num
from safety_cultivate_task t
left join market_config mc on mc.market_tenant = t.market_tenant

    mc.status = true

        and t.market_tenant = #{query.marketTenant}


        and t.market_tenant in

            #{marketTenantId}



        and t.cultivate_start_time >= #{query.period.begin} and t.cultivate_start_time <
        #{query.period.end}

SELECT mc.market_tenant, COALESCE ( sub.total_num, 0 ) AS total_num, mc.market_name FROM market_config mc LEFT JOIN ( SELECT market_tenant, COUNT( 1 ) AS total_num FROM safety_cultivate_task
and market_tenant = #{query.marketTenant}
and market_tenant in
#{marketTenantId}
and cultivate_start_time >= #{query.period.begin} and cultivate_start_time < #{query.period.end}
GROUP BY market_tenant ) sub ON mc.market_tenant = sub.market_tenant WHERE mc.`status` = TRUE AND mc.deleted = 0 ORDER BY sub.total_num DESC

select distinct t.`id`, t.`code`, t.`name`, t.`theme_id`, t.`theme_name`, t.`cultivate_start_time`, t.`cultivate_end_time`, t.`exam_task_id`, t.`cultivate_user_number`, t.`cultivate_mode`, t.`cultivate_mode_name`, t.`cultivate_target`, t.`cultivate_target_name`, t.`cultivate_address`, t.`speaker`, t.`charge_user_id`, t.`charge_user_name`, t.`cultivate_content`, t.`cultivate_task_status`, t.`cultivate_task_status_name`, t.`market_tenant`, mc.`market_name` from safety_cultivate_task t left join market_config mc on mc.market_tenant = t.market_tenant
mc.status = true
and ( t.name like concat('%',#{query.keyword},'%') or t.theme_name like concat('%',#{query.keyword},'%') )
and t.cultivate_target = #{query.cultivateType}
and t.cultivate_mode = #{query.cultivateMode}
and t.cultivate_task_status = #{query.status}
and t.market_tenant = #{query.marketTenant}
and t.market_tenant in
#{marketTenantId}
and t.cultivate_start_time >= #{query.period.begin} and t.cultivate_start_time < #{query.period.end}
order by t.create_time desc
